import { segmentsPageCount, type Segment } from "@/lib/segments"

export type DocumentSegment = Segment & {
  /** Stable domain id for the item that produced this segment. */
  sourceId?: string
}

export type SegmentBounds = {
  x: number
  y: number
  width: number
  height: number
}

export type SegmentAnchor = {
  id: string
  segmentId: string
  /** 1-based page/frame number. */
  pageNumber: number
  /** Normalized page-local rectangle. Omit for whole-page anchors. */
  bounds?: SegmentBounds
}

export type SegmentedPage = {
  pageNumber: number
  width?: number
  height?: number
}

export type SegmentRow = {
  id: string
  label?: string
  /** Generic display grouping only; domain vote/output semantics stay outside. */
  segments: DocumentSegment[]
}

export type SegmentedDocumentModel = {
  pages: SegmentedPage[]
  /** Viewport/navigation projection used for page ownership and jumps. */
  segments: DocumentSegment[]
  /** Optional page-local targets for segment-level navigation and overlays. */
  anchors?: SegmentAnchor[]
  /** Optional generic row projection for visual ribbons or grouped legends. */
  rows?: SegmentRow[]
}

export function createSegmentedDocumentModel({
  anchors,
  pageCount,
  pages,
  rows,
  segments,
}: {
  anchors?: SegmentAnchor[]
  pageCount?: number
  pages?: SegmentedPage[]
  rows?: SegmentRow[]
  segments: DocumentSegment[]
}): SegmentedDocumentModel {
  return {
    pages:
      pages ?? createSegmentedPages(pageCount ?? segmentsPageCount(segments)),
    segments,
    ...(anchors ? { anchors } : null),
    ...(rows ? { rows } : null),
  }
}

export function createSegmentedPages(pageCount: number): SegmentedPage[] {
  const count =
    Number.isFinite(pageCount) && pageCount > 0 ? Math.floor(pageCount) : 0
  return Array.from({ length: count }, (_, index) => ({
    pageNumber: index + 1,
  }))
}

"use client"

import * as React from "react"

import type { SegmentedDocumentModel } from "./segmented-document-model"
import {
  useSegmentViewportController,
  type SegmentedDocumentViewport,
} from "./use-segment-viewport-controller"

export type SegmentedDocumentContextValue = {
  model: SegmentedDocumentModel
  viewport: SegmentedDocumentViewport
}

const SegmentedDocumentContext =
  React.createContext<SegmentedDocumentContextValue | null>(null)

export function SegmentedDocumentProvider({
  children,
  model,
}: {
  children: React.ReactNode
  model: SegmentedDocumentModel
}) {
  const viewport = useSegmentViewportController({ segments: model.segments })
  const value = React.useMemo<SegmentedDocumentContextValue>(
    () => ({ model, viewport }),
    [model, viewport]
  )

  return (
    <SegmentedDocumentContext.Provider value={value}>
      {children}
    </SegmentedDocumentContext.Provider>
  )
}

export function useSegmentedDocument(): SegmentedDocumentContextValue {
  const context = React.useContext(SegmentedDocumentContext)
  if (!context) {
    throw new Error(
      "useSegmentedDocument must be used within SegmentedDocumentProvider."
    )
  }
  return context
}

export function useSegmentedDocumentViewport(): SegmentedDocumentViewport {
  return useSegmentedDocument().viewport
}

export function useSegmentedDocumentModel(): SegmentedDocumentModel {
  return useSegmentedDocument().model
}

"use client"

import * as React from "react"

import type { DocumentSegment, SegmentAnchor } from "./segmented-document-model"
import { useSegmentedDocument } from "./segmented-document-provider"

export type SegmentedItemNavigationOptions = {
  behavior?: ScrollBehavior
  clearPreview?: boolean
}

export type SegmentedItemLink = {
  activeAnchor: SegmentAnchor | null
  activeAnchors: readonly SegmentAnchor[]
  activeItemId: string | null
  activeSegment: DocumentSegment | null
  clearPreview: () => void
  navigateItem: (
    itemId: string,
    options?: SegmentedItemNavigationOptions
  ) => void
  previewItem: (itemId: string | null) => void
  selectItem: (itemId: string | null) => void
  selectedItemId: string | null
}

export type SegmentedItemLinkOptions = {
  initialItemId?: string | null
}

const EMPTY_SEGMENT_ANCHORS: readonly SegmentAnchor[] = []

export function useSegmentedItemLink(
  options: SegmentedItemLinkOptions = {}
): SegmentedItemLink {
  const { model, viewport } = useSegmentedDocument()
  const [selectedItemId, setSelectedItemId] = React.useState<string | null>(
    null
  )
  const segmentByItemId = React.useMemo(
    () =>
      new Map(
        model.segments.map((segment) => [
          segment.sourceId ?? segment.id,
          segment,
        ])
      ),
    [model.segments]
  )
  const anchorsBySegmentId = React.useMemo(
    () =>
      (model.anchors ?? []).reduce((anchorsBySegmentId, anchor) => {
        const anchors = anchorsBySegmentId.get(anchor.segmentId)
        if (anchors) {
          anchors.push(anchor)
        } else {
          anchorsBySegmentId.set(anchor.segmentId, [anchor])
        }
        return anchorsBySegmentId
      }, new Map<string, SegmentAnchor[]>()),
    [model.anchors]
  )
  const previewSegment =
    model.segments.find(
      (segment) => segment.id === viewport.model.previewSegmentId
    ) ?? null
  const selectedSegment = selectedItemId
    ? (segmentByItemId.get(selectedItemId) ?? null)
    : null
  const activeSegment = previewSegment ?? selectedSegment
  const activeItemId = activeSegment
    ? (activeSegment.sourceId ?? activeSegment.id)
    : selectedItemId
  const activeAnchors = activeSegment
    ? (anchorsBySegmentId.get(activeSegment.id) ?? EMPTY_SEGMENT_ANCHORS)
    : EMPTY_SEGMENT_ANCHORS
  const activeAnchor = activeAnchors[0] ?? null

  React.useEffect(() => {
    if (selectedItemId && !segmentByItemId.has(selectedItemId)) {
      setSelectedItemId(null)
    }
  }, [segmentByItemId, selectedItemId])

  React.useEffect(() => {
    const initialItemId = options.initialItemId ?? null
    if (
      !initialItemId ||
      selectedItemId != null ||
      !segmentByItemId.has(initialItemId)
    ) {
      return
    }
    setSelectedItemId(initialItemId)
  }, [options.initialItemId, segmentByItemId, selectedItemId])

  const clearPreview = viewport.interaction.clearPreview

  const navigateSegment = React.useCallback(
    (
      segment: DocumentSegment,
      options?: SegmentedItemNavigationOptions
    ) => {
      const anchor = anchorsBySegmentId.get(segment.id)?.[0]
      if (anchor) {
        viewport.navigation.scrollToAnchor(anchor, options)
        return
      }
      viewport.navigation.scrollToSegmentStart(segment, options)
    },
    [anchorsBySegmentId, viewport.navigation]
  )

  const navigateItem = React.useCallback(
    (itemId: string, options?: SegmentedItemNavigationOptions) => {
      const segment = segmentByItemId.get(itemId)
      if (!segment) return

      navigateSegment(segment, options)
    },
    [navigateSegment, segmentByItemId]
  )

  const previewItem = React.useCallback(
    (itemId: string | null) => {
      if (!itemId) {
        viewport.interaction.clearPreview()
        return
      }

      const segment = segmentByItemId.get(itemId)
      if (!segment) return

      viewport.interaction.previewSegment(segment.id)
    },
    [segmentByItemId, viewport.interaction]
  )

  const selectItem = React.useCallback(
    (itemId: string | null) => {
      if (!itemId) {
        setSelectedItemId(null)
        return
      }

      if (!segmentByItemId.has(itemId)) return

      setSelectedItemId(itemId)
      viewport.interaction.clearPreview()
    },
    [segmentByItemId, viewport.interaction]
  )

  return React.useMemo(
    () => ({
      activeAnchor,
      activeAnchors,
      activeItemId,
      activeSegment,
      clearPreview,
      navigateItem,
      previewItem,
      selectItem,
      selectedItemId,
    }),
    [
      activeAnchor,
      activeAnchors,
      activeItemId,
      activeSegment,
      clearPreview,
      navigateItem,
      previewItem,
      selectItem,
      selectedItemId,
    ]
  )
}

"use client"

import * as React from "react"

import {
  getSegmentInteractionState,
  type SegmentInteraction,
  type SegmentInteractionState,
} from "@/lib/segment-interaction"
import { firstSegmentPage, type Segment } from "@/lib/segments"

import type { DocumentSegment, SegmentAnchor } from "./segmented-document-model"
import { useSegmentInteraction } from "./use-segment-interaction"

const RAIL_VISIBILITY_MARGIN = 24
const PROGRAMMATIC_SCROLL_WINDOW_MS = 120
const USER_SCROLL_IDLE_MS = 400

export interface SegmentViewportModel extends SegmentInteractionState {
  scrollProgress: number
}

export type SegmentDocumentHandle = {
  getViewportElement?: () => HTMLElement | null
  scrollToPage: (page: number, options?: ScrollToOptions) => void
  scrollToAnchor?: (anchor: SegmentAnchor, options?: ScrollToOptions) => void
  scrollToPageArea?: (
    target: {
      pageNumber: number
      top: number
      left?: number
      width?: number
      height?: number
    },
    options?: ScrollToOptions
  ) => void
}

export type SegmentNavigationOptions = ScrollToOptions & {
  clearPreview?: boolean
}

export interface SegmentViewportController {
  model: SegmentViewportModel
  interaction: SegmentInteraction
  documentHandlers: {
    onCurrentPageChange: (page: number) => void
    onScrollProgressChange: (progress: number) => void
    setDocumentHandle: (handle: SegmentDocumentHandle | null) => void
  }
  navigation: {
    scrollToPage: (page: number, options?: SegmentNavigationOptions) => void
    scrollToSegmentStart: (
      segment: DocumentSegment,
      options?: SegmentNavigationOptions
    ) => void
    scrollToAnchor: (
      anchor: SegmentAnchor,
      options?: SegmentNavigationOptions
    ) => void
  }
  rail: {
    setViewportElement: (element: HTMLElement | null) => void
    setPageElement: (page: number, element: HTMLElement | null) => void
    onPointerEnter: () => void
    onPointerLeave: () => void
    onScroll: () => void
  }
}

interface RailFollowState {
  isPointerInsideRail: boolean
  isUserScrollingRail: boolean
  lastProgrammaticScrollAt: number
  idleTimer: number | null
}

export function useSegmentViewportController({
  segments,
}: {
  segments: Segment[]
}): SegmentViewportController {
  const [currentPage, setCurrentPage] = React.useState<number | null>(1)
  const [scrollProgress, setScrollProgress] = React.useState(0)
  const documentHandleRef = React.useRef<SegmentDocumentHandle | null>(null)
  const interaction = useSegmentInteraction()
  const { clearPreview } = interaction
  const railViewportRef = React.useRef<HTMLElement | null>(null)
  const pageElementByNumberRef = React.useRef(new Map<number, HTMLElement>())
  const railFollowStateRef = React.useRef<RailFollowState>({
    isPointerInsideRail: false,
    isUserScrollingRail: false,
    lastProgrammaticScrollAt: 0,
    idleTimer: null,
  })

  const model = React.useMemo<SegmentViewportModel>(() => {
    const interactionState = getSegmentInteractionState({
      segments,
      currentPage,
      interaction,
    })

    return {
      ...interactionState,
      scrollProgress,
    }
  }, [currentPage, interaction, scrollProgress, segments])

  const onCurrentPageChange = React.useCallback((page: number) => {
    setCurrentPage(normalizePage(page))
  }, [])

  const onScrollProgressChange = React.useCallback((progress: number) => {
    setScrollProgress(clamp01(progress))
  }, [])

  const setDocumentHandle = React.useCallback(
    (handle: SegmentDocumentHandle | null) => {
      documentHandleRef.current = handle
    },
    []
  )

  const scrollToPage = React.useCallback(
    (page: number, options?: SegmentNavigationOptions) => {
      const normalizedPage = normalizePage(page)
      if (normalizedPage == null) return

      if (options?.clearPreview !== false) interaction.clearPreview()
      const scrollOptions = segmentScrollOptions(options)
      if (scrollOptions) {
        documentHandleRef.current?.scrollToPage(normalizedPage, scrollOptions)
      } else {
        documentHandleRef.current?.scrollToPage(normalizedPage)
      }
    },
    [interaction]
  )

  const scrollToSegmentStart = React.useCallback(
    (segment: DocumentSegment, options?: SegmentNavigationOptions) => {
      const page = firstSegmentPage(segment.pages)
      if (page == null) return

      scrollToPage(page, options)
    },
    [scrollToPage]
  )

  const scrollToAnchor = React.useCallback(
    (anchor: SegmentAnchor, options?: SegmentNavigationOptions) => {
      const normalizedPage = normalizePage(anchor.pageNumber)
      if (normalizedPage == null) return

      if (options?.clearPreview !== false) interaction.clearPreview()
      const scrollOptions = segmentScrollOptions(options)
      const handle = documentHandleRef.current
      if (!handle) return

      if (handle.scrollToAnchor) {
        if (scrollOptions) {
          handle.scrollToAnchor(anchor, scrollOptions)
        } else {
          handle.scrollToAnchor(anchor)
        }
        return
      }

      if (anchor.bounds && handle.scrollToPageArea) {
        const target = {
          pageNumber: normalizedPage,
          left: toPageAreaPercent(anchor.bounds.x),
          top: toPageAreaPercent(anchor.bounds.y),
          width: toPageAreaPercent(anchor.bounds.width),
          height: toPageAreaPercent(anchor.bounds.height),
        }
        if (scrollOptions) {
          handle.scrollToPageArea(target, scrollOptions)
        } else {
          handle.scrollToPageArea(target)
        }
        return
      }

      if (scrollOptions) {
        handle.scrollToPage(normalizedPage, scrollOptions)
      } else {
        handle.scrollToPage(normalizedPage)
      }
    },
    [interaction]
  )

  const followCurrentPage = React.useCallback((page: number | null) => {
    const normalizedPage = normalizePage(page)
    if (normalizedPage == null) return

    const state = railFollowStateRef.current
    if (state.isPointerInsideRail || state.isUserScrollingRail) return

    const viewport = railViewportRef.current
    const target = pageElementByNumberRef.current.get(normalizedPage)
    if (!viewport || !target) return

    const viewportRect = viewport.getBoundingClientRect()
    const targetRect = target.getBoundingClientRect()
    const minTop = viewportRect.top + RAIL_VISIBILITY_MARGIN
    const maxBottom = viewportRect.bottom - RAIL_VISIBILITY_MARGIN

    if (targetRect.top >= minTop && targetRect.bottom <= maxBottom) return

    const targetTop =
      target.offsetTop - viewport.clientHeight / 2 + target.offsetHeight / 2

    state.lastProgrammaticScrollAt = performance.now()
    viewport.scrollTo?.({
      top: Math.max(0, targetTop),
      behavior: "smooth",
    })
  }, [])

  React.useLayoutEffect(() => {
    followCurrentPage(currentPage)
  }, [currentPage, followCurrentPage])

  React.useEffect(() => {
    const state = railFollowStateRef.current
    return () => {
      const timer = state.idleTimer
      if (timer != null) window.clearTimeout(timer)
    }
  }, [])

  React.useEffect(() => {
    setCurrentPage(1)
    setScrollProgress(0)
    clearPreview()
  }, [clearPreview, segments])

  const setPageElement = React.useCallback(
    (page: number, element: HTMLElement | null) => {
      const normalizedPage = normalizePage(page)
      if (normalizedPage == null) return

      if (element) {
        pageElementByNumberRef.current.set(normalizedPage, element)
      } else {
        pageElementByNumberRef.current.delete(normalizedPage)
      }
    },
    []
  )

  const handleRailScroll = React.useCallback(() => {
    const state = railFollowStateRef.current
    const elapsed = performance.now() - state.lastProgrammaticScrollAt
    if (elapsed < PROGRAMMATIC_SCROLL_WINDOW_MS) return

    state.isUserScrollingRail = true
    if (state.idleTimer != null) window.clearTimeout(state.idleTimer)
    state.idleTimer = window.setTimeout(() => {
      state.isUserScrollingRail = false
      state.idleTimer = null
    }, USER_SCROLL_IDLE_MS)
  }, [])

  const rail = React.useMemo(
    () => ({
      setViewportElement: (element: HTMLElement | null) => {
        railViewportRef.current = element
      },
      setPageElement,
      onPointerEnter: () => {
        railFollowStateRef.current.isPointerInsideRail = true
      },
      onPointerLeave: () => {
        railFollowStateRef.current.isPointerInsideRail = false
      },
      onScroll: handleRailScroll,
    }),
    [handleRailScroll, setPageElement]
  )

  const documentHandlers = React.useMemo(
    () => ({
      onCurrentPageChange,
      onScrollProgressChange,
      setDocumentHandle,
    }),
    [onCurrentPageChange, onScrollProgressChange, setDocumentHandle]
  )

  const navigation = React.useMemo(
    () => ({
      scrollToPage,
      scrollToAnchor,
      scrollToSegmentStart,
    }),
    [scrollToAnchor, scrollToPage, scrollToSegmentStart]
  )

  return React.useMemo(
    () => ({
      model,
      interaction,
      documentHandlers,
      navigation,
      rail,
    }),
    [documentHandlers, interaction, model, navigation, rail]
  )
}

function normalizePage(page: number | null | undefined): number | null {
  return page != null && Number.isInteger(page) && page > 0 ? page : null
}

function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0
  return Math.min(1, Math.max(0, value))
}

function toPageAreaPercent(value: number): number {
  if (!Number.isFinite(value)) return 0
  return value >= 0 && value <= 1 ? value * 100 : value
}

function segmentScrollOptions(
  options: SegmentNavigationOptions | undefined
): ScrollToOptions | undefined {
  if (!options) return undefined
  const { clearPreview: _clearPreview, ...scrollOptions } = options
  return Object.keys(scrollOptions).length > 0 ? scrollOptions : undefined
}

export type SegmentedDocumentViewportModel = SegmentViewportModel
export type SegmentedDocumentHandle = SegmentDocumentHandle
export type SegmentedDocumentViewport = SegmentViewportController
export type SegmentedDocumentHandlers =
  SegmentViewportController["documentHandlers"]
export type SegmentedDocumentNavigation =
  SegmentViewportController["navigation"]
